using System.IO.Enumeration;
using Microsoft.Extensions.Options;

namespace Roslyn.Workbench.Mcp.Workspace.Resolution;

/// <summary>
/// Recognises conventional generated filenames and auto-generated source headers.
/// </summary>
internal sealed class GeneratedSourceClassifier : IGeneratedSourceClassifier
{
    private const int _headerInspectionLength = 2048;
    private readonly string[] _exceptionPatterns;
    private readonly IWorkspacePathComparison _pathComparison;
    private readonly IFileSystem _fileSystem;

    /// <summary>
    /// Initializes a new instance of the <see cref="GeneratedSourceClassifier"/> class.
    /// </summary>
    /// <param name="options">The effective generated-source policy and exceptions.</param>
    /// <param name="pathComparison">The platform-aware path comparison service.</param>
    /// <param name="fileSystem">The file-system abstraction used for relative path calculations.</param>
    public GeneratedSourceClassifier(
        IOptions<WorkspaceOptions> options,
        IWorkspacePathComparison pathComparison,
        IFileSystem fileSystem)
    {
        _exceptionPatterns = options.Value.GeneratedSourceExceptions
            .Select(static pattern => pattern.Replace('\\', '/'))
            .ToArray();

        _pathComparison = pathComparison;
        _fileSystem = fileSystem;
    }

    /// <inheritdoc/>
    public async ValueTask<bool> IsGeneratedLookingAsync(
        Document document,
        string workspaceRoot,
        CancellationToken cancellationToken)
    {
        if (IsExcepted(document, workspaceRoot))
        {
            return false;
        }

        var filename = document.FilePath is null
            ? document.Name
            : _fileSystem.Path.GetFileName(document.FilePath);

        if (HasGeneratedFilename(filename))
        {
            return true;
        }

        var text = await document.GetTextAsync(cancellationToken);
        var inspectedLength = Math.Min(text.Length, _headerInspectionLength);
        var header = text.ToString(TextSpan.FromBounds(0, inspectedLength));

        return header.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase)
            || header.Contains("<autogenerated", StringComparison.OrdinalIgnoreCase);
    }

    private bool IsExcepted(Document document, string workspaceRoot)
    {
        if (document.FilePath is null || _exceptionPatterns.Length == 0)
        {
            return false;
        }

        var relativePath = _fileSystem.Path
            .GetRelativePath(workspaceRoot, document.FilePath)
            .Replace('\\', '/');

        var ignoreCase = _pathComparison.GetComparison(document.FilePath) == StringComparison.OrdinalIgnoreCase;
        return _exceptionPatterns.Any(pattern =>
            FileSystemName.MatchesSimpleExpression(pattern, relativePath, ignoreCase));
    }

    private static bool HasGeneratedFilename(string filename)
    {
        return filename.EndsWith(".g.cs", StringComparison.OrdinalIgnoreCase)
            || filename.EndsWith(".g.i.cs", StringComparison.OrdinalIgnoreCase)
            || filename.EndsWith(".generated.cs", StringComparison.OrdinalIgnoreCase)
            || filename.EndsWith(".designer.cs", StringComparison.OrdinalIgnoreCase)
            || filename.Contains("TemporaryGeneratedFile_", StringComparison.OrdinalIgnoreCase);
    }
}
